 "content": "def transform(grid):
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    # Find the embedded horizontal pattern (the only contiguous non-background run).
    template = None
    for row in grid:
        c = 0
        while c < len(row):
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < len(row) and row[c] != bg:
                c += 1
            run = row[start:c]
            if len(run) >= 2:
                template = run[:]
                break
        if template is not None:
            break
    if template is None:
        return out
    # Remaining isolated object color marks locations to expand into the template.
    template_colors = set(template)
    marker = next((v for v in counts if v != bg and v not in template_colors), None)
    if marker is None:
        return out
    center = len(template) // 2
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == marker:
                for j, color in enumerate(template):
                    x = c + j - center
                    if 0 <= x < len(row):
                        out[r][x] = color
    return out

if __name__ == '__main__':
    pass
